        if isinstance(coords, list) and 0 <= i < len(coords):
            return coords[i]
        return None

    def d(i, j):
        if dist is not None:
            if isinstance(dist, dict):
                if i in dist and isinstance(dist[i], dict) and j in dist[i]:
                    return dist[i][j]
                if (i, j) in dist:
                    return dist[(i, j)]
                if (j, i) in dist:
                    return dist[(j, i)]
            else:
                try:
                    return dist[i][j]
                except Exception:
                    pass
        ci = coord_of(i)
        cj = coord_of(j)
        if ci is None or cj is None:
            return 0
        dx = ci[0] - cj[0]
        dy = ci[1] - cj[1]
        return (dx * dx + dy * dy) ** 0.5

    customers = [c for c in customer_ids if c != depot]
    if not customers:
        return []

    total_demand = 0
    for c in customers:
        total_demand += demand_of(c)
    if capacity is None or capacity <= 0:
        capacity = total_demand

    unvisited = {}
    for c in customers:
        unvisited[c] = True
    tour = []

    def depot_key(c):
        return (-d(depot, c), demand_of(c), c)

    start = min(customers, key=depot_key)
    current = start
    tour.append(current)
    if current in unvisited:
        del unvisited[current]

    while unvisited:
        next_c = None
        best_key = None
        for c in unvisited:
            key = (d(current, c), -d(depot, c), demand_of(c), c)
            if best_key is None or key < best_key:
                best_key = key
                next_c = c
        tour.append(next_c)
        del unvisited[next_c]
        current = next_c

    n = len(tour)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + demand_of(tour[i])

    def seg_demand(i, j):
        return pref[j + 1] - pref[i]

    def seg_cost(i, j):
        cst = d(depot, tour[i]) + d(tour[j], depot)
        k = i
        while k < j:
            cst += d(tour[k], tour[k + 1])
            k += 1
        return cst

    INF = 10 ** 30
    dp = [INF] * (n + 1)
    nxt = [-1] * (n + 1)
    dp[n] = 0

    i = n - 1
    while i >= 0:
        best = INF
        best_j = -1
        j = i
        while j < n and seg_demand(i, j) <= capacity:
            val = seg_cost(i, j) + dp[j + 1]
            if val < best:
                best = val
                best_j = j
            j += 1
        dp[i] = best
        nxt[i] = best_j
        i -= 1

    routes = []
    i = 0
    while i < n and nxt[i] != -1:
        j = nxt[i]
        routes.append(tour[i:j + 1])
        i = j + 1

    if i < n:
        routes = []
        route = []
        load = 0
        for c in tour:
            dc = demand_of(c)
            if route and load + dc > capacity:
                routes.append(route)
                route = [c]
                load = dc
            else:
                route.append(c)
                load += dc
        if route:
            routes.append(route)

    def route_load(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        s = d(depot, rt[0]) + d(rt[-1], depot)
        for a, b in zip(rt, rt[1:]):
            s += d(a, b)
        return s

    improved = True
    while improved:
        improved = False
        idx = 0
        while idx < len(routes) - 1:
            a = routes[idx]
            b = routes[idx + 1]
            if a and b:
                la = route_load(a)
                lb = route_load(b)

                x = a[-1]
                dx = demand_of(x)
                if la - dx >= 0 and lb + dx <= capacity:
                    before = route_cost(a) + route_cost(b)
                    na = a[:-1]
                    nb = [x] + b
                    after = route_cost(na) + route_cost(nb)
                    if after < before:
                        routes[idx] = na
                        routes[idx + 1] = nb
                        improved = True
                        idx += 1
                        continue

                y = b[0]
                dy = demand_of(y)
                if la + dy <= capacity and lb - dy >= 0:
                    before = route_cost(a) + route_cost(b)
                    na = a + [y]
                    nb = b[1:]
                    after = route_cost(na) + route_cost(nb)
                    if after < before:
                        routes[idx] = na
                        routes[idx + 1] = nb
                        improved = True
                        idx += 1
                        continue
            idx += 1

    return routes
